local world = {player = nil, bullets = {}, enemies = {}, particles = {}, powerups = {}, stars = {}, shootTimer = 0, spawnTimer = 0, difficultyMultiplier = 1, stats = {kills = 0, damageTaken = 0}}
function world.init(width, height) world.initStars(width, height); world.reset(width, height) end
function world.initStars(width, height) world.stars = {}; local count = math.floor((width * height) / 3500); for i = 1, count do table.insert(world.stars, {x = math.random(0, width), y = math.random(0, height), size = math.random(1, 3), speed = math.random(10, 80), brightness = math.random(150, 255)}) end end
function world.reset(width, height) local baseSize = math.min(width, height); world.player = {x = width / 2, y = height - math.min(height * 0.12, 80), width = baseSize * 0.055, height = baseSize * 0.055, speed = 350, hp = 100, maxHp = 100, fireRate = 0.09, bulletSpeed = baseSize * 0.95, damage = 1, invincible = 0, engineGlow = 0, shipType = "striker", skill = "none", color = {0.3, 0.7, 1}}; world.bullets = {}; world.enemies = {}; world.particles = {}; world.powerups = {}; world.shootTimer = 0; world.spawnTimer = 0; world.difficultyMultiplier = 1; world.stats = {kills = 0, damageTaken = 0} end
function world.updateStars(dt, height) for _, star in ipairs(world.stars) do star.y = star.y + star.speed * dt; if star.y > height then star.y = 0; star.x = math.random(0, love.graphics.getWidth()) end end end
function world.updatePlayer(dt, input, screenWidth, utils) local p = world.player; local move = 0; if input.left then move = move - 1 end; if input.right then move = move + 1 end; if move ~= 0 then p.x = p.x + move * p.speed * dt end; if utils then p.x = utils.clamp(p.x, p.width/2, screenWidth - p.width/2) end; p.engineGlow = p.engineGlow + dt * 10; if p.invincible > 0 then p.invincible = p.invincible - dt end end
function world.shoot() local p = world.player; local bw = math.max(4, p.width * 0.15); local bh = math.max(8, p.height * 0.35); if p.skill == "double" then table.insert(world.bullets, {x = p.x - 8, y = p.y - p.height/2, width = bw, height = bh, color = {0.4, 0.9, 1}, damage = p.damage, penetrate = 0, angle = -0.08}); table.insert(world.bullets, {x = p.x + 8, y = p.y - p.height/2, width = bw, height = bh, color = {0.4, 0.9, 1}, damage = p.damage, penetrate = 0, angle = 0.08}) elseif p.skill == "penetrate" then table.insert(world.bullets, {x = p.x, y = p.y - p.height/2, width = bw * 1.3, height = bh * 1.2, color = {1, 0.4, 0.6}, damage = p.damage, penetrate = 3, angle = 0}) else table.insert(world.bullets, {x = p.x, y = p.y - p.height/2, width = bw, height = bh, color = {0.4, 0.9, 1}, damage = p.damage, penetrate = 0, angle = 0}) end end
function world.updateBullets(dt) for i = #world.bullets, 1, -1 do local b = world.bullets[i]; b.y = b.y - world.player.bulletSpeed * dt; if b.angle and b.angle ~= 0 then b.x = b.x + b.angle * world.player.bulletSpeed * dt end; if b.y < -20 or b.x < -20 or b.x > love.graphics.getWidth() + 20 then table.remove(world.bullets, i) end end end
function world.spawnEnemy(screenWidth, baseSize, roundNum, rounds) local etype = rounds.getEnemyType(roundNum, 0); local speedMult = rounds.getSpeedMult(roundNum); local types = {scout = {w = baseSize*0.045, h = baseSize*0.045, hp = 1, speed = baseSize*0.18, score = 10, color = {1,0.3,0.3}, sway = false}, fighter = {w = baseSize*0.055, h = baseSize*0.055, hp = 2, speed = baseSize*0.12, score = 25, color = {1,0.6,0.2}, sway = true, swayAmount = baseSize*0.08, swaySpeed = 3}, tank = {w = baseSize*0.065, h = baseSize*0.065, hp = 5, speed = baseSize*0.07, score = 50, color = {0.8,0.2,0.8}, sway = true, swayAmount = baseSize*0.04, swaySpeed = 1.5}, speeder = {w = baseSize*0.04, h = baseSize*0.055, hp = 1, speed = baseSize*0.30, score = 40, color = {0.2,0.8,1}, sway = false}}; local et = types[etype] or types.scout; table.insert(world.enemies, {x = math.random(math.floor(et.w), math.floor(screenWidth - et.w)), y = -50, width = et.w, height = et.h, hp = et.hp, maxHp = et.hp, speed = et.speed * world.difficultyMultiplier * speedMult, score = et.score, color = et.color, rotation = 0, rotSpeed = math.random(-2, 2), sway = et.sway, swayAmount = et.swayAmount or 0, swaySpeed = et.swaySpeed or 0, swayOffset = math.random() * 10, type = etype}) end
function world.updateEnemies(dt, screenWidth, screenHeight, utils, onDeath) for i = #world.enemies, 1, -1 do local e = world.enemies[i]; e.y = e.y + e.speed * dt; e.rotation = e.rotation + e.rotSpeed * dt; if e.sway then e.x = e.x + math.sin(love.timer.getTime() * e.swaySpeed + e.swayOffset) * e.swayAmount * dt end; e.x = utils.clamp(e.x, e.width/2, screenWidth - e.width/2); if e.y > screenHeight + 50 then table.remove(world.enemies, i) elseif utils.checkCollision(e, world.player) and world.player.invincible <= 0 then world.player.hp = world.player.hp - 20; world.player.invincible = 1.5; world.stats.damageTaken = world.stats.damageTaken + 20; world.createExplosion(world.player.x, world.player.y - 10, {1, 0.5, 0}, 30); table.remove(world.enemies, i); if world.player.hp <= 0 and onDeath then onDeath() end end end end
function world.checkBulletHits(utils, onScore, onKill) for i = #world.bullets, 1, -1 do local hit = false; for j = #world.enemies, 1, -1 do if utils.checkCollision(world.bullets[i], world.enemies[j]) then local e = world.enemies[j]; local b = world.bullets[i]; e.hp = e.hp - b.damage; world.createExplosion(b.x, b.y, {1, 1, 0.5}, 8); if e.hp <= 0 then world.createExplosion(e.x, e.y, e.color, 25); onScore(e.score); onKill(); world.stats.kills = world.stats.kills + 1; if math.random() < 0.08 then world.spawnPowerup(e.x, e.y, math.min(love.graphics.getWidth(), love.graphics.getHeight())) end; table.remove(world.enemies, j) end; if b.penetrate > 0 then b.penetrate = b.penetrate - 1 else hit = true end; break end end; if hit then table.remove(world.bullets, i) end end end
function world.spawnPowerup(x, y, baseSize) local types = {"health", "speed", "rapid"}; local type = types[math.random(1, #types)]; local colors = {health = {0.2,1,0.3}, speed = {0.3,0.6,1}, rapid = {1,0.8,0.2}}; table.insert(world.powerups, {x = x, y = y, width = baseSize*0.035, height = baseSize*0.035, type = type, color = colors[type], pulse = 0}) end
function world.updatePowerups(dt, screenHeight, utils, onCollect) for i = #world.powerups, 1, -1 do local p = world.powerups[i]; p.y = p.y + 80 * dt; p.pulse = p.pulse + dt * 4; if utils.checkCollision(p, world.player) then world.applyPowerup(p.type); onCollect(); table.remove(world.powerups, i) elseif p.y > screenHeight + 20 then table.remove(world.powerups, i) end end end
function world.applyPowerup(type) local p = world.player; if type == "health" then p.hp = math.min(p.maxHp, p.hp + 30); world.createExplosion(p.x, p.y, {0.2, 1, 0.3}, 15) elseif type == "speed" then p.speed = math.min(love.graphics.getHeight() * 0.8, p.speed + 50); world.createExplosion(p.x, p.y, {0.3, 0.6, 1}, 15) elseif type == "rapid" then p.fireRate = math.max(0.05, p.fireRate - 0.02); world.createExplosion(p.x, p.y, {1, 0.8, 0.2}, 15) end end
function world.createExplosion(x, y, color, count) for i = 1, count do local angle = math.random() * math.pi * 2; local speed = math.random(50, 250); table.insert(world.particles, {x = x, y = y, vx = math.cos(angle)*speed, vy = math.sin(angle)*speed, life = math.random(0.3, 0.8), maxLife = 0.8, size = math.random(2, 5), color = color}) end end
function world.updateParticles(dt) for i = #world.particles, 1, -1 do local p = world.particles[i]; p.x = p.x + p.vx * dt; p.y = p.y + p.vy * dt; p.life = p.life - dt; p.vy = p.vy + 50 * dt; if p.life <= 0 then table.remove(world.particles, i) end end end
function world.drawStars() for _, star in ipairs(world.stars) do love.graphics.setColor(star.brightness/255, star.brightness/255, star.brightness/255*1.2); love.graphics.circle("fill", star.x, star.y, star.size * 0.6) end end
function world.drawPlayer() local p = world.player; if p.invincible > 0 and math.sin(love.timer.getTime() * 15) <= 0 then return end; local c = p.color or {0.3, 0.7, 1}; love.graphics.push(); love.graphics.translate(p.x, p.y); local fh = 15 + math.sin(p.engineGlow) * 5; love.graphics.setColor(c[1]*0.6, c[2]*0.8, 1, 0.6); love.graphics.polygon("fill", -p.width*0.2, p.height/2, 0, p.height/2+fh, p.width*0.2, p.height/2); love.graphics.setColor(c[1]*0.8, c[2]*0.9, 1, 0.4); love.graphics.polygon("fill", -p.width*0.12, p.height/2, 0, p.height/2+fh*0.7, p.width*0.12, p.height/2); love.graphics.setColor(c[1], c[2], c[3]); love.graphics.polygon("fill", 0, -p.height/2, p.width/2, p.height/3, p.width/3, p.height/2, -p.width/3, p.height/2, -p.width/2, p.height/3); love.graphics.setColor(c[1]*1.2, c[2]*1.1, c[3]*1.2, 0.7); love.graphics.polygon("line", 0, -p.height/2, p.width/2, p.height/3, p.width/3, p.height/2, -p.width/3, p.height/2, -p.width/2, p.height/3); love.graphics.setColor(0.9, 0.95, 1); love.graphics.circle("fill", 0, -p.height*0.12, p.width*0.15); love.graphics.setColor(c[1]*0.5, c[2]*0.5, c[3]*0.8); love.graphics.polygon("fill", p.width/2, p.height/3, p.width/2+p.width*0.12, p.height/2-p.height*0.12, p.width/3, p.height/2); love.graphics.polygon("fill", -p.width/2, p.height/3, -p.width/2-p.width*0.12, p.height/2-p.height*0.12, -p.width/3, p.height/2); love.graphics.pop() end
function world.drawBullets() for _, b in ipairs(world.bullets) do love.graphics.setColor(b.color[1], b.color[2], b.color[3]); love.graphics.rectangle("fill", b.x-b.width/2, b.y-b.height/2, b.width, b.height); love.graphics.setColor(b.color[1], b.color[2], b.color[3], 0.3); love.graphics.rectangle("fill", b.x-b.width/2-2, b.y-b.height/2-2, b.width+4, b.height+4) end end
function world.drawEnemies() for _, e in ipairs(world.enemies) do love.graphics.push(); love.graphics.translate(e.x, e.y); love.graphics.rotate(e.rotation); if e.type == "scout" then love.graphics.setColor(e.color[1], e.color[2], e.color[3]); love.graphics.polygon("fill", 0, -e.height/2, e.width/2, 0, 0, e.height/2, -e.width/2, 0); love.graphics.setColor(1, 0.5, 0.5, 0.5); love.graphics.polygon("line", 0, -e.height/2, e.width/2, 0, 0, e.height/2, -e.width/2, 0) elseif e.type == "fighter" then love.graphics.setColor(e.color[1], e.color[2], e.color[3]); love.graphics.polygon("fill", 0, e.height/2, e.width/2, -e.height/3, 0, -e.height/2, -e.width/2, -e.height/3); love.graphics.setColor(1, 0.7, 0.3, 0.6); love.graphics.polygon("line", 0, e.height/2, e.width/2, -e.height/3, 0, -e.height/2, -e.width/2, -e.height/3) elseif e.type == "tank" then love.graphics.setColor(e.color[1], e.color[2], e.color[3]); local r = e.width/2; love.graphics.polygon("fill", r, 0, r/2, r*0.866, -r/2, r*0.866, -r, 0, -r/2, -r*0.866, r/2, -r*0.866); love.graphics.setColor(0.9, 0.4, 0.9, 0.5); love.graphics.polygon("line", r, 0, r/2, r*0.866, -r/2, r*0.866, -r, 0, -r/2, -r*0.866, r/2, -r*0.866) else love.graphics.setColor(e.color[1], e.color[2], e.color[3]); love.graphics.polygon("fill", 0, -e.height/2, e.width/3, 0, 0, e.height/2, -e.width/3, 0) end; if e.hp < e.maxHp then love.graphics.rotate(-e.rotation); love.graphics.setColor(0.3, 0.3, 0.3); love.graphics.rectangle("fill", -e.width/2, -e.height/2-10, e.width, 4); love.graphics.setColor(1, 0.3, 0.3); love.graphics.rectangle("fill", -e.width/2, -e.height/2-10, e.width*(e.hp/e.maxHp), 4) end; love.graphics.pop() end end
function world.drawPowerups() for _, p in ipairs(world.powerups) do local pulse = 1 + math.sin(p.pulse) * 0.2; love.graphics.setColor(p.color[1], p.color[2], p.color[3], 0.8); love.graphics.circle("fill", p.x, p.y, (p.width/2)*pulse); love.graphics.setColor(1, 1, 1, 0.6); love.graphics.circle("line", p.x, p.y, (p.width/2)*pulse + 3); love.graphics.setColor(1, 1, 1, 0.9); local s = p.width * 0.25; if p.type == "health" then love.graphics.rectangle("fill", p.x-s*0.3, p.y-s, s*0.6, s*2); love.graphics.rectangle("fill", p.x-s, p.y-s*0.3, s*2, s*0.6) elseif p.type == "speed" then love.graphics.polygon("fill", p.x+s*0.5, p.y-s, p.x-s*0.3, p.y, p.x+s*0.2, p.y, p.x-s*0.5, p.y+s, p.x+s*0.3, p.y, p.x-s*0.2, p.y) else love.graphics.polygon("fill", p.x-s*0.5, p.y-s*0.6, p.x, p.y, p.x-s*0.5, p.y+s*0.6); love.graphics.polygon("fill", p.x, p.y-s*0.6, p.x+s*0.5, p.y, p.x, p.y+s*0.6) end end end
function world.drawParticles() for _, p in ipairs(world.particles) do local alpha = p.life / p.maxLife; love.graphics.setColor(p.color[1], p.color[2], p.color[3], alpha); love.graphics.circle("fill", p.x, p.y, p.size * alpha) end end
return world
